-- Frozen differential fixtures generated from real NumPy 2.3.5
local np=require("luaray_core")
assert(np._version=="0.109.0-dev")
local checks,cases=0,0
local function deep(a,b,desc)
    assert(type(a)==type(b),desc..': type mismatch: '..type(a)..' vs '..type(b))
    if type(a)=='table' then
        assert(#a==#b,desc..': length mismatch: '..#a..' vs '..#b)
        for i=1,#a do deep(a[i],b[i],desc..'['..i..']') end
    else
        assert(a==b,desc..': '..tostring(a)..' vs '..tostring(b))
    end
    checks=checks+1
end
do
local r=np.random.default_rng(9876)
local x=np.transpose(np.astype(np.arange(18,"int64"):reshape({3,2,3}),"int32"),{3,2,1})
local before=x:tolist()
local y=r:permuted(x,nil)
deep(y.dtype,"int32","9876/(3, 2, 3)/int32/transpose/None/copy dtype")
deep(y:tolist(),{{{10,12,0},{17,16,13}},{{7,9,14},{4,3,2}},{{11,5,1},{6,8,15}}},"9876/(3, 2, 3)/int32/transpose/None/copy values")
deep(x:tolist(),{{{0,6,12},{3,9,15}},{{1,7,13},{4,10,16}},{{2,8,14},{5,11,17}}},"9876/(3, 2, 3)/int32/transpose/None/copy source")
deep(r:raw_hex(),"6a0b558b51e8b55b","9876/(3, 2, 3)/int32/transpose/None/copy pcg")
cases=cases+1; end
