local x=np.astype(np.arange(8,"int64"):reshape({2,1,4}),"int64")
local before=x:tolist()
local out=np.zeros({2,1,4},"int64")
local y=r:permuted(x,-1,out)
deep(y.dtype,"int64","9876/(2, 1, 4)/int64/plain/-1/out_new dtype")
deep(y:tolist(),{{{0,1,2,3}},{{4,6,7,5}}},"9876/(2, 1, 4)/int64/plain/-1/out_new values")
deep(x:tolist(),{{{0,1,2,3}},{{4,5,6,7}}},"9876/(2, 1, 4)/int64/plain/-1/out_new source")
assert(rawequal(y,out),"out must return identical ndarray")
deep(r:raw_hex(),"79d5d3707e1b5fef","9876/(2, 1, 4)/int64/plain/-1/out_new pcg")
cases=cases+1; end
