local x=np.transpose(np.astype(np.arange(8,"int64"):reshape({1,2,4}),"float32"),{3,2,1})
local before=x:tolist()
local y=r:permuted(x,1,x)
deep(y.dtype,"float32","9876/(1, 2, 4)/float32/transpose/0/out_same dtype")
deep(y:tolist(),{{{0.0},{4.0}},{{1.0},{6.0}},{{2.0},{7.0}},{{3.0},{5.0}}},"9876/(1, 2, 4)/float32/transpose/0/out_same values")
deep(x:tolist(),{{{0.0},{4.0}},{{1.0},{6.0}},{{2.0},{7.0}},{{3.0},{5.0}}},"9876/(1, 2, 4)/float32/transpose/0/out_same source")
assert(rawequal(y,x),"out must return identical ndarray")
deep(r:raw_hex(),"79d5d3707e1b5fef","9876/(1, 2, 4)/float32/transpose/0/out_same pcg")
cases=cases+1; end
